contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(v > 0, "v must be positive");

        c.depositsCount(); if (__ESBMC_reverted()) return;

        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        assert(reverted || (thisBalanceAfter == thisBalanceBefore + v && cBalanceAfter + v == cBalanceBefore && depositsAfter == depositsBefore));
    }

    receive() external payable {}
}

